"""undo, redo and history (docs/undo.md)."""

from binkeep import journal
from binkeep.bins import normalize
from binkeep.errors import DataError, Refused

OPS = journal.OPS


class Stacks:
    def __init__(self):
        self.done = []
        self.undone = []
        self.dropped = set()
        self.ops = []          # all operation entries, file order
        self.undo_line = {}    # op seq -> latest undo line

    def push_op(self, e):
        self.ops.append(e)
        self.dropped.update(x["seq"] for x in self.undone)
        self.undone = []
        self.done.append(e)

    def undo(self, line):
        t = line.get("target")
        if not self.done or self.done[-1]["seq"] != t or isinstance(t, bool):
            raise DataError("journal", f"undo #{line['seq']} does not match the stacks")
        e = self.done.pop()
        self.undone.append(e)
        self.undo_line[e["seq"]] = line
        return e

    def redo(self, line):
        t = line.get("target")
        if not self.undone or self.undone[-1]["seq"] != t or isinstance(t, bool):
            raise DataError("journal", f"redo #{line['seq']} does not match the stacks")
        e = self.undone.pop()
        self.done.append(e)
        return e


def build(entries):
    st = Stacks()
    for e in entries:
        op = e["op"]
        if op in OPS:
            st.push_op(e)
        elif op == "undo":
            st.undo(e)
        elif op == "redo":
            st.redo(e)
    return st


def _effects(line):
    eff = line.get("effects")
    if not isinstance(eff, list):
        raise DataError("journal", f"#{line['seq']}: no effects")
    return eff


def _plan_undo(ctx, e, store):
    """List of (bin, new quantity) in order."""
    op = e["op"]
    if op == "fix":
        raise Refused("barrier", "a fix cannot be undone")
    if e.get("v") == 2:
        return [(x["bin"], x["before"]) for x in reversed(_effects(e))]
    if op == "count":
        raise Refused("irreversible", "format 1 count cannot be undone")
    sku = e.get("sku")
    cur = {}
    def q(code):
        return cur.get(code, store.qty(sku, code))
    out = []
    try:
        if op == "receive":
            code = normalize(e["bin"])
            units = e["qty"]
            if e.get("uom") == "pk":
                if sku not in ctx.items:
                    raise Refused("unknown-sku", f"no item {sku}")
                units *= ctx.items[sku].pack_size
            out.append((code, q(code) - units))
        elif op == "issue":
            for code, n in reversed(e["picks"]):
                code = normalize(code)
                cur[code] = q(code) + n
                out.append((code, cur[code]))
        elif op == "move":
            f, t = normalize(e["from"]), normalize(e["to"])
            cur[t] = q(t) - e["qty"]
            out.append((t, cur[t]))
            out.append((f, q(f) + e["qty"]))
    except (KeyError, TypeError, ValueError):
        raise DataError("journal", f"#{e['seq']}: malformed line") from None
    return out


def _plan_redo(e, undo_line):
    return [(x["bin"], x["before"]) for x in reversed(_effects(undo_line))]


def run(ctx, kind, steps):
    st = build(ctx.entries)
    store = ctx.store.copy()
    seq = journal.next_seq(ctx.entries)
    new = []
    for _ in range(steps):
        if kind == "undo":
            if not st.done:
                raise Refused("nothing-to-undo", "nothing to undo")
            e = st.done[-1]
            plan = _plan_undo(ctx, e, store)
        else:
            if not st.undone:
                raise Refused("nothing-to-redo", "nothing to redo")
            e = st.undone[-1]
            plan = _plan_redo(e, st.undo_line[e["seq"]])
        for code, _q in plan:
            if code not in ctx.bins:
                raise Refused("unknown-bin", f"no bin {code}")
        sku = e.get("sku", "")
        effects = []
        try:
            for code, qty in plan:
                before = store.qty(sku, code)
                store.set(sku, code, qty, force=True)
                effects.append({"bin": code, "before": before, "after": qty})
        except TypeError:
            raise DataError("journal", f"#{e['seq']}: malformed line") from None
        line = journal.entry(seq, kind, ctx.by, sku, target=e["seq"], effects=effects)
        line["_op"] = e["op"]
        new.append(line)
        (st.undo if kind == "undo" else st.redo)(line)
        seq += 1
    return store, new


def entry_text(line):
    head = f"#{line['seq']} {line['op']} {line['sku']} (#{line['target']} {line['_op']})"
    return [head] + [f"  {x['bin']} {x['before']} -> {x['after']}" for x in line["effects"]]


def history(ctx, limit):
    st = build(ctx.entries)
    done = {e["seq"] for e in st.done}
    undone = {e["seq"] for e in st.undone}
    out = []
    for e in reversed(st.ops[-limit:]):
        s = e["seq"]
        if s in done:
            status = "barrier" if e["op"] == "fix" else "done"
        elif s in undone:
            status = "undone"
        else:
            status = "dropped"
        out.append(f"{s:>5}  {e['op']:<7}  {e.get('sku', ''):<10}  {status}")
    return out
